import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { collection, addDoc } from 'firebase/firestore';
import { db } from '../config/firebase';
import { 
    Lock, Mail, User, Building, Map, 
    MessageCircle, Rocket, CheckCircle, Loader2 
} from 'lucide-react';

const IcebreakerLanding = () => {
    const navigate = useNavigate();
    const { login, signup, resetPassword, currentUser } = useAuth();
    
    const [isLogin, setIsLogin] = useState(true);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [username, setUsername] = useState('');
    
    const [waitlistEmail, setWaitlistEmail] = useState('');
    const [waitlistLoading, setWaitlistLoading] = useState(false);
    const [waitlistSuccess, setWaitlistSuccess] = useState(false);
    
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');

    const handleAuth = async (e) => {
        e.preventDefault();
        setError('');
        setMessage('');
        setLoading(true);

        try {
            if (isLogin) {
                await login(email, password);
                navigate('/icebreaker');
            } else {
                await signup(email, password, username);
                setMessage('Account created! Please check your email for a verification link.');
                setIsLogin(true);
            }
        } catch (err) {
            setError(err.message || 'Failed to authenticate');
        } finally {
            setLoading(false);
        }
    };

    const handleResetPassword = async () => {
        if (!email) {
            setError('Please enter your email address first.');
            return;
        }
        try {
            setMessage('');
            setError('');
            setLoading(true);
            await resetPassword(email);
            setMessage('Check your inbox for password reset instructions.');
        } catch (err) {
            setError('Failed to reset password.');
        } finally {
            setLoading(false);
        }
    };

    const handleWaitlist = async (e) => {
        e.preventDefault();
        if (!waitlistEmail) return;
        
        setWaitlistLoading(true);
        try {
            await addDoc(collection(db, 'icebreaker_waitlist'), {
                email: waitlistEmail,
                timestamp: new Date()
            });
            setWaitlistSuccess(true);
            setWaitlistEmail('');
        } catch (err) {
            console.error("Error joining waitlist:", err);
        } finally {
            setWaitlistLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-[#050505] text-white flex flex-col md:flex-row font-sans">
            
            {/* Left Side: Marketing */}
            <div className="w-full md:w-3/5 p-8 md:p-16 flex flex-col justify-center relative overflow-hidden bg-gradient-to-br from-blue-900/20 via-black to-teal-900/20 overflow-y-auto">
                {/* Decorative glowing orbs */}
                <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-500/20 rounded-full blur-[120px] pointer-events-none"></div>
                <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-teal-500/20 rounded-full blur-[120px] pointer-events-none"></div>
                
                <div className="z-10 max-w-2xl">
                    <h1 className="text-5xl md:text-7xl font-bold mb-6 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-teal-300">
                        Icebreaker
                    </h1>
                    <p className="text-xl md:text-2xl text-gray-300 mb-4 leading-relaxed">
                        The real-world social network powering authentic connections, local discovery, and business growth.
                    </p>
                    <p className="text-sm text-orange-400/90 font-semibold mb-10 tracking-wide uppercase flex items-center gap-2">
                        <span className="inline-block w-2 h-2 rounded-full bg-orange-500 animate-pulse"></span>
                        100% Human · Zero AI · Real Conversations
                    </p>
                    
                    {/* Feature boxes — Live Social Map top-right, For Businesses top-left */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-8">
                        {/* TOP-LEFT: Live Social Map */}
                        <div className="bg-white/5 border border-white/10 p-6 rounded-2xl backdrop-blur-sm hover:border-teal-500/40 hover:bg-teal-500/5 transition-all">
                            <Map className="text-teal-400 mb-3 w-7 h-7" />
                            <h3 className="text-xl font-semibold mb-2">Live Social Map</h3>
                            <p className="text-gray-400 text-sm leading-relaxed">
                                See who's physically nearby in real-time. Color-coded status dots show exactly what each person is open to — before you approach them.
                            </p>
                        </div>
                        {/* TOP-RIGHT: For Businesses */}
                        <div className="bg-white/5 border border-white/10 p-6 rounded-2xl backdrop-blur-sm hover:border-blue-500/40 hover:bg-blue-500/5 transition-all">
                            <Building className="text-blue-400 mb-3 w-7 h-7" />
                            <h3 className="text-xl font-semibold mb-2">For Businesses</h3>
                            <p className="text-gray-400 text-sm leading-relaxed">
                                Create digital storefronts, launch targeted B2B bounties, and drive foot traffic with high-density Geo-Swarms. Put your brand where your customers already are.
                            </p>
                        </div>
                        {/* BOTTOM-LEFT: Real-Time Chat */}
                        <div className="bg-white/5 border border-white/10 p-6 rounded-2xl backdrop-blur-sm hover:border-purple-500/40 hover:bg-purple-500/5 transition-all">
                            <MessageCircle className="text-purple-400 mb-3 w-7 h-7" />
                            <h3 className="text-xl font-semibold mb-2">Real-Time Chat</h3>
                            <p className="text-gray-400 text-sm leading-relaxed">
                                Instant messaging built on dual-write architecture for lightning-fast, reliable communication with read receipts and rich media.
                            </p>
                        </div>
                        {/* BOTTOM-RIGHT: Aether Network */}
                        <div className="bg-white/5 border border-white/10 p-6 rounded-2xl backdrop-blur-sm hover:border-orange-500/40 hover:bg-orange-500/5 transition-all">
                            <Rocket className="text-orange-400 mb-3 w-7 h-7" />
                            <h3 className="text-xl font-semibold mb-2">Aether Network</h3>
                            <p className="text-gray-400 text-sm leading-relaxed">
                                Empower your sales team. Tap into a network of users ready to engage with your products and services, right now, right here.
                            </p>
                        </div>
                    </div>

                    {/* Color Status System */}
                    <div className="bg-white/3 border border-white/10 rounded-2xl p-6 mb-8">
                        <h3 className="text-lg font-bold mb-1 text-white flex items-center gap-2">
                            <span className="inline-block w-2 h-2 rounded-full bg-green-400"></span>
                            Engagement Color System
                        </h3>
                        <p className="text-gray-400 text-xs mb-4 leading-relaxed">
                            Set your status in-app with one tap. Others nearby see your dot color before approaching — no awkward guessing, just honest signals.
                        </p>
                        <div className="grid grid-cols-1 gap-2">
                            <div className="flex items-start gap-3">
                                <span className="mt-1 flex-shrink-0 w-3 h-3 rounded-full bg-green-400 shadow-[0_0_8px_rgba(74,222,128,0.8)]"></span>
                                <p className="text-sm"><span className="text-green-400 font-semibold">Green — Business &amp; Networking</span> <span className="text-gray-400">· Open to professional connections, pitches, partnerships, or career conversations right now.</span></p>
                            </div>
                            <div className="flex items-start gap-3">
                                <span className="mt-1 flex-shrink-0 w-3 h-3 rounded-full bg-orange-400 shadow-[0_0_8px_rgba(251,146,60,0.8)]"></span>
                                <p className="text-sm"><span className="text-orange-400 font-semibold">Orange — Friendship</span> <span className="text-gray-400">· Looking to meet new people, hang out, and make genuine social connections in the real world.</span></p>
                            </div>
                            <div className="flex items-start gap-3">
                                <span className="mt-1 flex-shrink-0 w-3 h-3 rounded-full bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.8)]"></span>
                                <p className="text-sm"><span className="text-red-400 font-semibold">Red — Love / Dating / Flirting</span> <span className="text-gray-400">· Open to romantic connection. A clear, consensual signal so everyone knows the vibe before approaching.</span></p>
                            </div>
                            <div className="flex items-start gap-3">
                                <span className="mt-1 flex-shrink-0 w-3 h-3 rounded-full bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,0.8)]"></span>
                                <p className="text-sm"><span className="text-blue-400 font-semibold">Blue — Do Not Disturb</span> <span className="text-gray-400">· Visible on the map but not open to new contact right now. Respects your space without going invisible.</span></p>
                            </div>
                            <div className="flex items-start gap-3">
                                <span className="mt-1 flex-shrink-0 w-3 h-3 rounded-full bg-yellow-400 shadow-[0_0_8px_rgba(250,204,21,0.8)]"></span>
                                <p className="text-sm"><span className="text-yellow-400 font-semibold">Yellow — Custom</span> <span className="text-gray-400">· You write it. Set any message from your settings — "looking for a chess partner", "ask me about my startup", anything goes.</span></p>
                            </div>
                            <div className="flex items-start gap-3 mt-1 pt-2 border-t border-white/10">
                                <span className="mt-1 flex-shrink-0 w-3 h-3 rounded-full bg-gray-600 border border-gray-500"></span>
                                <p className="text-sm"><span className="text-gray-300 font-semibold">Ghost / Invisible Mode</span> <span className="text-gray-400">· Location hidden. You browse the map but nobody sees you. One tap in the app to go dark — instant privacy, any time.</span></p>
                            </div>
                        </div>
                    </div>

                    {/* No-AI Statement */}
                    <div className="bg-gradient-to-br from-orange-950/50 to-orange-900/20 border border-orange-500/30 rounded-2xl p-5 mb-10 shadow-[0_0_30px_rgba(249,115,22,0.08)]">
                        <span className="text-orange-400 font-bold text-base block mb-3 flex items-center gap-2">
                            <span className="inline-block w-2 h-2 rounded-full bg-orange-500 animate-pulse"></span>
                            100% Real. 100% Human. No Exceptions.
                        </span>
                        <p className="text-sm text-gray-300 leading-relaxed mb-3">
                            Every piece of content on Icebreaker — every video, audio clip, photo, and message — is <strong className="text-orange-300">created directly inside the app</strong>. There is no upload button. That's intentional. You can't import content made elsewhere, which means you can't import AI-generated content. What you see is what someone actually made, right here, right now.
                        </p>
                        <p className="text-sm text-gray-300 leading-relaxed mb-3">
                            We enforce this at the platform level so the feed stays authentic. No AI ghostwriters drafting your messages. No generated avatars. No synthetic voices. No AI-edited highlight reels. Just people, being people.
                        </p>
                        <p className="text-sm text-orange-400/80 leading-relaxed font-medium">
                            AI bots are also strictly prohibited from the platform. Icebreaker is built to connect real humans with real humans — full stop.
                        </p>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-4 items-center">
                        <button 
                            onClick={() => window.location.href = '/icebreaker'}
                            className="w-full sm:w-auto px-8 py-4 bg-gradient-to-r from-blue-600 to-teal-500 hover:from-blue-500 hover:to-teal-400 text-white font-bold rounded-full transition-all transform hover:scale-105 shadow-[0_0_20px_rgba(59,130,246,0.5)]"
                        >
                            View App Demo
                        </button>
                    </div>

                    {/* Waitlist Section */}
                    <div className="mt-10 pt-8 border-t border-white/10 relative">
                        <div className="absolute top-0 left-1/4 w-1/2 h-[1px] bg-gradient-to-r from-transparent via-orange-500 to-transparent"></div>
                        <h4 className="text-xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-orange-400 to-red-400 flex items-center">
                            Break the Ice Early 🔥 <span className="text-gray-300 text-sm font-normal ml-3 mt-1">Join the waitlist for first access</span>
                        </h4>
                        
                        {waitlistSuccess ? (
                            <div className="flex items-center text-orange-400 bg-orange-400/10 p-4 rounded-lg border border-orange-400/20 shadow-[0_0_15px_rgba(249,115,22,0.2)]">
                                <CheckCircle className="mr-2" />
                                You're on the list! We'll notify you when we launch.
                            </div>
                        ) : (
                            <form onSubmit={handleWaitlist} className="flex flex-col sm:flex-row gap-3">
                                <input 
                                    type="email" 
                                    required
                                    placeholder="Enter your email"
                                    value={waitlistEmail}
                                    onChange={(e) => setWaitlistEmail(e.target.value)}
                                    className="flex-1 bg-black/50 border border-orange-500/30 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-orange-500 focus:shadow-[0_0_10px_rgba(249,115,22,0.3)] transition-all"
                                />
                                <button 
                                    type="submit"
                                    disabled={waitlistLoading}
                                    className="px-8 py-3 bg-gradient-to-r from-orange-500 to-red-600 hover:from-orange-400 hover:to-red-500 text-white font-bold rounded-lg transition-all shadow-[0_0_15px_rgba(249,115,22,0.4)] transform hover:scale-105 flex items-center justify-center border-none"
                                >
                                    {waitlistLoading ? <Loader2 className="animate-spin" /> : 'Join Waitlist'}
                                </button>
                            </form>
                        )}
                    </div>
                </div>
            </div>

            {/* Right Side: Auth Portal */}

            <div className="w-full md:w-2/5 p-8 flex flex-col justify-center items-center bg-black/80 border-l border-white/10">
                <div className="w-full max-w-md bg-white/5 border border-white/10 p-8 rounded-2xl backdrop-blur-md shadow-2xl">
                    <h2 className="text-3xl font-bold mb-2 text-center">
                        {isLogin ? 'Welcome Back' : 'Create Account'}
                    </h2>
                    <p className="text-gray-400 text-center mb-8">
                        {isLogin ? 'Sign in to access your dashboard' : 'Join the Icebreaker network'}
                    </p>

                    {error && (
                        <div className="mb-6 p-3 bg-red-500/20 border border-red-500/50 rounded-lg text-red-200 text-sm text-center">
                            {error}
                        </div>
                    )}
                    {message && (
                        <div className="mb-6 p-3 bg-green-500/20 border border-green-500/50 rounded-lg text-green-200 text-sm text-center">
                            {message}
                        </div>
                    )}
                    {currentUser && !currentUser.emailVerified && (
                        <div className="mb-6 p-3 bg-yellow-500/20 border border-yellow-500/50 rounded-lg text-yellow-200 text-sm text-center">
                            Please verify your email address to access all features. Check your inbox.
                        </div>
                    )}

                    <form onSubmit={handleAuth} className="space-y-4">
                        {!isLogin && (
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
                                    <User />
                                </div>
                                <input
                                    type="text"
                                    required
                                    placeholder="Username"
                                    value={username}
                                    onChange={(e) => setUsername(e.target.value)}
                                    className="w-full bg-black/50 border border-white/20 rounded-lg pl-10 pr-4 py-3 text-white focus:outline-none focus:border-blue-500 transition-colors"
                                />
                            </div>
                        )}
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
                                <Mail />
                            </div>
                            <input
                                type="email"
                                required
                                placeholder="Email Address"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="w-full bg-black/50 border border-white/20 rounded-lg pl-10 pr-4 py-3 text-white focus:outline-none focus:border-blue-500 transition-colors"
                            />
                        </div>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
                                <Lock />
                            </div>
                            <input
                                type="password"
                                required
                                placeholder="Password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full bg-black/50 border border-white/20 rounded-lg pl-10 pr-4 py-3 text-white focus:outline-none focus:border-blue-500 transition-colors"
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full py-3 mt-4 bg-gradient-to-r from-blue-600 to-teal-500 hover:from-blue-500 hover:to-teal-400 text-white font-bold rounded-lg transition-all shadow-lg flex justify-center items-center"
                        >
                            {loading ? <Loader2 className="animate-spin" /> : (isLogin ? 'Sign In' : 'Sign Up')}
                        </button>
                    </form>

                    <div className="mt-6 text-center text-sm text-gray-400 space-y-3">
                        {isLogin && (
                            <div>
                                <button onClick={handleResetPassword} className="text-blue-400 hover:text-blue-300 transition-colors">
                                    Forgot your password?
                                </button>
                            </div>
                        )}
                        <div>
                            {isLogin ? "Don't have an account? " : "Already have an account? "}
                            <button 
                                onClick={() => setIsLogin(!isLogin)} 
                                className="text-teal-400 hover:text-teal-300 font-semibold transition-colors"
                            >
                                {isLogin ? 'Sign up' : 'Sign in'}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default IcebreakerLanding;
